/*
 * Generated by Sean Toolbox. Do not edit; the host rewrites this file.
 *
 * Wayland grants global shortcuts and other applications' windows to the
 * compositor only. This KWin script registers the configured shortcuts,
 * switches matching windows, and starts applications through the user
 * systemd template units installed by the host.
 */

const PROFILES = __PROFILES__;
const LAUNCHER = __LAUNCHER__;
const LAUNCH_COOLDOWN_MS = 5000;

const cycles = {};
const launched = {};

function log(message) {
    print('sean-toolbox: ' + message);
}

function basename(value) {
    const match = /[\/\\]([^\/\\]*)$/.exec(value);
    return match ? match[1] : value;
}

function window_id(window) {
    return String(window.internalId);
}

function matches(window, matcher) {
    const target = String(matcher).toLowerCase();
    const base = basename(target);
    const window_class = String(window.resourceClass || '').toLowerCase();
    const window_name = String(window.resourceName || '').toLowerCase();
    return window_class === target || window_name === target ||
           window_class === base || window_name === base;
}

function windows_for(matcher) {
    return workspace.windowList().filter(function (window) {
        return (window.normalWindow || window.dialog) && matches(window, matcher);
    });
}

function start_unit(unit) {
    callDBus('org.freedesktop.systemd1', '/org/freedesktop/systemd1',
             'org.freedesktop.systemd1.Manager', 'StartUnit', unit, 'replace');
}

function launch(id) {
    const now = Date.now();
    if (launched[id] && now - launched[id] < LAUNCH_COOLDOWN_MS) {
        return;
    }
    launched[id] = now;
    log('launch ' + id);
    start_unit('sean-toolbox-launch@' + id + '.service');
}

function show_projects() {
    start_unit('sean-toolbox-show@projects.service');
}

function activate(window, profile) {
    window.minimized = false;
    if (profile.maximize) {
        window.setMaximize(true, true);
    }
    workspace.activeWindow = window;
}

function toggle(profile) {
    const windows = windows_for(profile.matcher);
    log('toggle ' + profile.id + ' windows=' + windows.length);
    if (windows.length === 0) {
        launch(profile.id);
        return;
    }
    const active = workspace.activeWindow;
    const ids = windows.map(window_id);
    const previous = cycles[profile.id] || { order: [], last: null };
    const order = previous.order.filter(function (id) {
        return ids.indexOf(id) >= 0;
    });
    ids.forEach(function (id) {
        if (order.indexOf(id) < 0) {
            order.push(id);
        }
    });
    if (windows.length === 1) {
        const window = windows[0];
        if (active && window_id(active) === ids[0]) {
            window.minimized = true;
            cycles[profile.id] = { order: order, last: null };
            return;
        }
        activate(window, profile);
        cycles[profile.id] = { order: order, last: ids[0] };
        return;
    }
    let next = 0;
    if (active) {
        const index = order.indexOf(window_id(active));
        if (index >= 0) {
            next = index + 1;
        }
    }
    if (next === 0 && previous.last) {
        const index = order.indexOf(previous.last);
        if (index >= 0) {
            next = index + 1;
        }
    }
    if (next >= order.length) {
        if (!profile.cycle_continuous) {
            windows.forEach(function (window) {
                window.minimized = true;
            });
            cycles[profile.id] = { order: order, last: null };
            return;
        }
        next = 0;
    }
    const target = order[next];
    windows.forEach(function (window) {
        if (window_id(window) === target) {
            activate(window, profile);
        }
    });
    cycles[profile.id] = { order: order, last: target };
}

function toggle_callback(profile) {
    return function () {
        toggle(profile);
    };
}

PROFILES.forEach(function (profile) {
    // An empty shortcut keeps an unbound action so the host can still invoke
    // this toggle; KGlobalAccel already uses "none" for that state.
    const key = profile.hotkey || 'none';
    if (!registerShortcut('Sean Toolbox: ' + profile.id,
                          'Sean Toolbox: ' + profile.name,
                          key, toggle_callback(profile))) {
        log('could not register ' + key + ' for ' + profile.id);
    }
});

if (LAUNCHER) {
    if (!registerShortcut('Sean Toolbox: projects',
                          'Sean Toolbox: recent projects',
                          LAUNCHER, show_projects)) {
        log('could not register ' + LAUNCHER + ' for recent projects');
    }
}

// Wayland has no client-side skip-taskbar hint. The recent-projects surface is
// a panel, not a task: keep it out of the taskbar and the window switcher when
// KWin maps it. The window title is the translated `ui.launcher.title`
// ("Sean Toolbox · …"); the management window is titled exactly "Sean Toolbox".
const LAUNCHER_CAPTION = 'Sean Toolbox · ';

function hide_launcher_panel(window) {
    if (String(window.resourceClass || '').toLowerCase() !== 'sean-toolbox' ||
        String(window.caption || '').indexOf(LAUNCHER_CAPTION) !== 0) {
        return;
    }
    if (!window.skipTaskbar) {
        window.skipTaskbar = true;
    }
    if (!window.skipSwitcher) {
        window.skipSwitcher = true;
    }
}

function watch_launcher_panel(window) {
    hide_launcher_panel(window);
    // The caption may arrive after the compositor maps the surface.
    window.captionChanged.connect(function () {
        hide_launcher_panel(window);
    });
}

workspace.windowList().forEach(watch_launcher_panel);
workspace.windowAdded.connect(watch_launcher_panel);